import { assetUrl } from "@/lib/asset";

/**
 * Rich-universe phase — streamed deep star catalogue.
 *
 * 61,814 real HYG v4.4 rows (mag <= 8.5, 0.99 MB raw Float32 LE) generated by
 * scripts/generate-star-catalog.mjs into public/stars-deep.bin — served on
 * demand, never bundled into the single-file build. Same record layout as the
 * bundled catalog: [RA deg, DEC deg, Vmag, B-V] per row, brightest-first.
 *
 * The fetch is memoized at module scope; failures clear the memo so a later
 * scene can retry. Low quality tiers simply never call this.
 */
import { STAR_COUNT } from "@/data/stars/starCatalog";

const URL_DEEP = assetUrl("/stars-deep.bin");

let pending: Promise<Float32Array | null> | null = null;
let loadedCount = 0;

/** Record count of a raw deep payload (guards against truncated downloads). */
export function deepStarCount(data: Float32Array): number {
  return Math.floor(data.length / 4);
}

export function deepStarsLoaded(): number {
  return loadedCount;
}

declare global {
  interface Window {
    __echoesStarsDeep?: () => { count: number; bytes: number };
  }
}

if (typeof window !== "undefined") {
  window.__echoesStarsDeep = () => ({ count: loadedCount, bytes: loadedCount * 16 });
}

export function loadDeepStars(): Promise<Float32Array | null> {
  if (!pending) {
    pending = fetch(URL_DEEP)
      .then((r) => {
        if (!r.ok) throw new Error(`deep stars HTTP ${r.status}`);
        return r.arrayBuffer();
      })
      .then((buf) => {
        const all = new Float32Array(buf);
        // tolerate trailing bytes but never a truncated record
        const data = all.length % 4 === 0 ? all : all.subarray(0, Math.floor(all.length / 4) * 4);
        const count = deepStarCount(data);
        if (count < STAR_COUNT) throw new Error(`deep stars too small: ${count}`);
        loadedCount = count;
        return data;
      })
      .catch(() => {
        pending = null; // allow retry when a later scene mounts
        return null;
      });
  }
  return pending;
}
